package com.booksyde.entity; import jakarta.persistence.*; import java.time.OffsetDateTime; import java.util.UUID; @Entity @Table(name="reviews",schema="public",uniqueConstraints=@UniqueConstraint(columnNames={"user_id","manga_id"})) public class ReviewEntity {@Id private UUID id; @Column(name="manga_id") private UUID mangaId; @Column(name="user_id") private UUID userId; private int rating; private String body; @Column(name="created_at",insertable=false,updatable=false) private OffsetDateTime createdAt; protected ReviewEntity(){} public ReviewEntity(UUID m,UUID u,int r,String b){id=UUID.randomUUID();mangaId=m;userId=u;rating=r;body=b;} public UUID getId(){return id;} public UUID getMangaId(){return mangaId;} public UUID getUserId(){return userId;} public int getRating(){return rating;} public String getBody(){return body;} public OffsetDateTime getCreatedAt(){return createdAt;} public void update(int r,String b){rating=r;body=b;}}